def page(rows, limit, after, team):
    if not isinstance(limit, int) or isinstance(limit, bool) or not 1 <= limit <= 50:
        raise ValueError("limit must be an integer from 1 to 50")

    def sort_key(row):
        return -row["score"], row["id"]

    selected = (row for row in rows if team is None or row["team"] == team)
    if after is not None:
        score, row_id = after
        cursor_key = (-score, row_id)
        selected = (row for row in selected if sort_key(row) > cursor_key)

    ordered = sorted(selected, key=sort_key)
    result = ordered[:limit]
    next_cursor = None
    if len(ordered) > limit:
        last = result[-1]
        next_cursor = [last["score"], last["id"]]
    return {"rows": result, "next": next_cursor}
